begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
insert into auth.users(id,email,raw_user_meta_data) values
 ('20000000-0000-0000-0000-000000000001','discussion-one@example.test','{}'),
 ('20000000-0000-0000-0000-000000000002','discussion-two@example.test','{}');
insert into public.reviews(id,user_id,media_type,tmdb_id,rating) values
 ('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','movie',1,5),
 ('30000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','movie',2,4);
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.set_review_like('30000000-0000-0000-0000-000000000001',true)$$,'like review');
select lives_ok($$select public.set_review_like('30000000-0000-0000-0000-000000000001',true)$$,'like is idempotent');
select is((select like_count from public.review_like_summaries(array['30000000-0000-0000-0000-000000000001']::uuid[])),1::bigint,'one like');
select lives_ok($$select public.create_review_comment('30000000-0000-0000-0000-000000000001',null,'root')$$,'create root');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.review_likes),0::bigint,'other users likes private');
select is((select liked from public.review_like_summaries(array['30000000-0000-0000-0000-000000000001']::uuid[])),false,'own state private');
select lives_ok($$select public.create_review_comment('30000000-0000-0000-0000-000000000001',(select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='root'),'reply')$$,'create reply');
select throws_ok($$select public.create_review_comment('30000000-0000-0000-0000-000000000001',(select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='reply'),'nested')$$,'22023',null,'nested replies rejected');
select throws_ok($$select public.create_review_comment('30000000-0000-0000-0000-000000000002',(select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='root'),'cross review')$$,'22023',null,'cross-review parent rejected');
select throws_ok($$select public.update_review_comment((select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='root'),'stolen')$$,'42501',null,'cannot edit others comment');
select throws_ok($$select public.delete_review_comment((select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='root'))$$,'42501',null,'cannot delete others comment');
select throws_ok($$insert into public.review_comments(review_id,user_id,body) values ('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000002','direct')$$,'42501',null,'direct writes denied');
select is((select comment_count from public.review_like_summaries(array['30000000-0000-0000-0000-000000000001']::uuid[])),2::bigint,'independent comment total');
select is((select count(*) from public.review_comments_page('30000000-0000-0000-0000-000000000001',(select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='root'),null,null,1)),1::bigint,'reply pagination returns the reply');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
update public.reviews set rating=4 where id='30000000-0000-0000-0000-000000000001';
select is((select count(*) from public.review_comments where review_id='30000000-0000-0000-0000-000000000001'),2::bigint,'editing review retains identifier and discussions');
select lives_ok($$select public.delete_review_comment((select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='root'))$$,'delete root');
select is((select count(*) from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='reply'),1::bigint,'reply survives tombstone');
select is((select comment_count from public.review_like_summaries(array['30000000-0000-0000-0000-000000000001']::uuid[])),1::bigint,'tombstone excluded');
select is((select count(*) from public.review_comments_page('30000000-0000-0000-0000-000000000001',null,null,null,10)),1::bigint,'root page preserves tombstone');
select lives_ok($$select public.set_review_like('30000000-0000-0000-0000-000000000001',false)$$,'unlike review');
select lives_ok($$select public.set_review_like('30000000-0000-0000-0000-000000000001',false)$$,'unlike idempotent');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select public.create_review_comment('30000000-0000-0000-0000-000000000001',null,'account root');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select public.create_review_comment('30000000-0000-0000-0000-000000000001',(select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='account root'),'survives account');
select is((select count(*) from public.review_comments_page('30000000-0000-0000-0000-000000000001',null,null,null,1)),1::bigint,'first root page is bounded');
select is((select count(*) from public.review_comments_page('30000000-0000-0000-0000-000000000001',null,(select created_at from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and parent_id is null order by created_at,id limit 1),(select id from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and parent_id is null order by created_at,id limit 1),10)),1::bigint,'cursor advances without duplication');
reset role;
delete from public.profiles where id='20000000-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(*) from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and body='survives account'),1::bigint,'other users reply survives author deletion');
select is((select count(*) from public.review_comments where review_id='30000000-0000-0000-0000-000000000001' and user_id is null and deleted_at is not null),2::bigint,'deleted account comments are tombstoned');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select is((select like_count from public.review_like_summaries(array['30000000-0000-0000-0000-000000000001']::uuid[])),0::bigint,'anonymous can read aggregate');
select throws_ok($$select public.create_review_comment('30000000-0000-0000-0000-000000000001',null,'anonymous')$$,'42501',null,'anonymous cannot create comments');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
delete from public.reviews where id='30000000-0000-0000-0000-000000000001';
select is((select count(*) from public.review_comments where review_id='30000000-0000-0000-0000-000000000001'),0::bigint,'review deletion cascades comments');
select * from finish();
rollback;
